# ============================================================
# 01e_table_2_1.R
# Table 2.1: How prime ministers depart — transition probabilities
# 2x2 transition matrix (previous PM departure → current PM departure)
# Updated with Starmer (N = 18 transitions, Attlee–Starmer)
# ============================================================

rm(list = ls())
.ROOT <- local({
  a <- commandArgs(trailingOnly = FALSE)
  m <- grep("^--file=", a, value = TRUE)
  if (length(m) == 1) normalizePath(file.path(dirname(sub("^--file=", "", m)), "..")) else getwd()
})
setwd(.ROOT)

if (!require("pacman")) install.packages("pacman")
pacman::p_load(dplyr, ggplot2, tidyr)

# ============================================================
# Data
# ============================================================
pms <- tribble(
  ~name,           ~party,        ~start,       ~end,         ~exit,
  "Attlee",        "Labour",      "1945-07-26", "1951-10-26", "electoral",
  "Churchill",     "Conservative","1951-10-26", "1955-04-05", "voluntary",
  "Eden",          "Conservative","1955-04-06", "1957-01-09", "voluntary",
  "Macmillan",     "Conservative","1957-01-10", "1963-10-18", "voluntary",
  "Douglas-Home",  "Conservative","1963-10-19", "1964-10-16", "electoral",
  "Wilson I",      "Labour",      "1964-10-16", "1970-06-19", "electoral",
  "Heath",         "Conservative","1970-06-19", "1974-03-04", "electoral",
  "Wilson II",     "Labour",      "1974-03-04", "1976-04-05", "voluntary",
  "Callaghan",     "Labour",      "1976-04-05", "1979-05-04", "electoral",
  "Thatcher",      "Conservative","1979-05-04", "1990-11-28", "internal",
  "Major",         "Conservative","1990-11-28", "1997-05-02", "electoral",
  "Blair",         "Labour",      "1997-05-02", "2007-06-27", "voluntary",
  "Brown",         "Labour",      "2007-06-27", "2010-05-11", "electoral",
  "Cameron",       "Conservative","2010-05-11", "2016-07-13", "no_choice",
  "May",           "Conservative","2016-07-13", "2019-07-24", "no_choice",
  "Johnson",       "Conservative","2019-07-24", "2022-09-06", "internal",
  "Truss",         "Conservative","2022-09-06", "2022-10-25", "internal",
  "Sunak",         "Conservative","2022-10-25", "2024-07-05", "electoral",
  "Starmer",       "Labour",      "2024-07-05", "2026-07-16", "internal"
) |>
  mutate(
    forced = as.integer(exit %in% c("internal", "no_choice"))
  )

# ============================================================
# Build transition matrix
# ============================================================
pms_lag <- pms |>
  mutate(prev_forced = lag(forced)) |>
  filter(!is.na(prev_forced))

n_trans <- nrow(pms_lag)
cat("N =", n_trans, "transitions\n\n")

trans <- table(
  Previous = ifelse(pms_lag$prev_forced == 1, "forced", "normal"),
  Current  = ifelse(pms_lag$forced == 1, "forced", "normal")
)
print(trans)

# Row percentages
prev_normal_forced  <- trans["normal", "forced"]
prev_normal_normal  <- trans["normal", "normal"]
prev_forced_forced  <- trans["forced", "forced"]
prev_forced_normal  <- trans["forced", "normal"]

pct_nn_forced <- round(100 * prev_normal_forced / (prev_normal_forced + prev_normal_normal))
pct_nn_normal <- round(100 * prev_normal_normal / (prev_normal_forced + prev_normal_normal))
pct_pf_forced <- round(100 * prev_forced_forced / (prev_forced_forced + prev_forced_normal))
pct_pf_normal <- round(100 * prev_forced_normal / (prev_forced_forced + prev_forced_normal))

cat(sprintf("\nPrev normal → forced: %d (%d%%)\n", prev_normal_forced, pct_nn_forced))
cat(sprintf("Prev normal → normal: %d (%d%%)\n", prev_normal_normal, pct_nn_normal))
cat(sprintf("Prev forced → forced: %d (%d%%)\n", prev_forced_forced, pct_pf_forced))
cat(sprintf("Prev forced → normal: %d (%d%%)\n", prev_forced_normal, pct_pf_normal))

# ============================================================
# Feedback loop test (logit) and runs test
# ============================================================
m_fb <- glm(forced ~ prev_forced, data = pms_lag, family = binomial)
p_logit <- round(summary(m_fb)$coefficients[2, 4], 2)
cat(sprintf("\nFeedback loop (logit): p = %.2f\n", p_logit))

# Runs test for clustering
forced_seq <- pms$forced
n1 <- sum(forced_seq)
n0 <- length(forced_seq) - n1
runs <- 1 + sum(forced_seq[-1] != forced_seq[-length(forced_seq)])
mu_runs <- 1 + 2 * n1 * n0 / (n1 + n0)
var_runs <- 2 * n1 * n0 * (2 * n1 * n0 - n1 - n0) /
  ((n1 + n0)^2 * (n1 + n0 - 1))
z_runs <- (runs - mu_runs) / sqrt(var_runs)
p_runs <- round(2 * pnorm(-abs(z_runs)), 3)
cat(sprintf("Runs test: p = %.3f\n", p_runs))

# ============================================================
# Figure: 2x2 transition matrix
# ============================================================

# Build data frame for tiles
tile_df <- tibble(
  row   = c(1, 1, 2, 2),
  col   = c(1, 2, 1, 2),
  count = c(prev_normal_forced, prev_normal_normal,
            prev_forced_forced, prev_forced_normal),
  pct   = c(pct_nn_forced, pct_nn_normal,
            pct_pf_forced, pct_pf_normal),
  # Shade: darker = higher percentage
  shade = c(pct_nn_forced, pct_nn_normal,
            pct_pf_forced, pct_pf_normal)
)

# Grey shading: map percentage to grey (higher % = darker)
# Use a range from light grey (#d9d9d9) to dark grey (#404040)
tile_df <- tile_df |>
  mutate(
    grey_val = 0.85 - 0.55 * (shade / 100),
    fill_col = rgb(grey_val, grey_val, grey_val)
  )

# Order fill colours for scale
fill_breaks <- tile_df$fill_col
names(fill_breaks) <- tile_df$fill_col

subtitle_text <- paste0(
  "After a forced departure, the successor is nearly three times more likely to be forced out (",
  pct_pf_forced, "% vs ", pct_nn_forced, "%).\n",
  "N = ", n_trans, " transitions (Attlee\u2013Starmer)."
)

caption_text <- paste0(
  "Forced = internal removal or no-choice resignation. Normal = electoral defeat or voluntary.\n",
  "Feedback loop (logit): p = ", format(p_logit, nsmall = 2),
  ". Runs test for clustering of forced departures: p = ", format(p_runs, nsmall = 3), "."
)

p <- ggplot(tile_df, aes(x = col, y = -row)) +
  geom_tile(aes(fill = fill_col), colour = "white", linewidth = 2,
            width = 0.95, height = 0.95) +
  scale_fill_identity() +
  # Count labels
  geom_text(aes(label = count), size = 10, fontface = "bold",
            nudge_y = 0.05) +
  # Percentage labels
  geom_text(aes(label = paste0("(", pct, "%)")), size = 7,
            nudge_y = -0.15) +
  # Row labels (left)
  annotate("text", x = 0.35, y = -1, label = "Previous PM\nnormal departure",
           size = 4, hjust = 1, lineheight = 0.9) +
  annotate("text", x = 0.35, y = -2, label = "Previous PM\nforced out",
           size = 4, hjust = 1, lineheight = 0.9) +
  # Column labels (bottom)
  annotate("text", x = 1, y = -2.65, label = "Forced out", size = 4) +
  annotate("text", x = 2, y = -2.65, label = "Normal departure", size = 4) +
  annotate("text", x = 1.5, y = -2.85, label = "Current PM departure",
           size = 4.5, fontface = "bold") +
  # Title and subtitle
  labs(
    title    = "Table 2.1: How prime ministers depart \u2014 transition probabilities",
    subtitle = subtitle_text,
    caption  = caption_text
  ) +
  coord_cartesian(xlim = c(-0.1, 2.7), ylim = c(-3.0, -0.3), clip = "off") +
  theme_void(base_size = 12) +
  theme(
    plot.title    = element_text(face = "bold", size = 14, hjust = 0,
                                margin = margin(b = 2)),
    plot.subtitle = element_text(size = 10, colour = "grey30", hjust = 0,
                                 lineheight = 1.2, margin = margin(b = 10)),
    plot.caption  = element_text(size = 8.5, colour = "grey40", hjust = 0.5,
                                 lineheight = 1.2, margin = margin(t = 10)),
    plot.margin   = margin(15, 15, 15, 15)
  )

ggsave("figures/table_2_1_transition.png", p, width = 8, height = 6, dpi = 300)
cat("\nSaved: figures/table_2_1_transition.png\n")
